43	#define SET_CTL_CB(ctl, ret, intf, addr, addr_len, rsp_hndl, user_data, data_len) do {                                                  \
44	    (ctl)->intf = intf;                                                       \
45	    (ctl)->addr = *addr;                                                      \
46	    (ctl)->addr_len = addr_len;                                               \
47	    (ctl)->rsp_hndl = rsp_hndl;                                               \
48	    (ctl)->user_data = NULL;                                                  \
49	    (ctl)->data_len = 0;                                                      \
50	    (ctl)->next = NULL;                                                       \
51	    if (user_data && (data_len > 0)) {                                        \
52	        (ctl)->user_data = malloc((size_t)(data_len));                                  \
53	        if (!(ctl)->user_data) {                                              \
54	            goto error_out;                                                   \
55	        }                                                                     \
56	        if (memset_s((void *)(ctl)->user_data, (size_t)(data_len), 0, (size_t)(data_len)) != 0) { \
57	            goto error_out;                                                   \
58	        }                                                                     \
59	        (ret) = memcpy_s((ctl)->user_data, (size_t)(data_len), user_data, (size_t)(data_len));      \
60	        (ctl)->data_len = data_len;                                           \
61	    }                                                                         \
62	} while (0)
