67	STATIC void slice_msg_free(void *ctl_cb)
68	{
69	    SEND_CTL_CB *cb = (SEND_CTL_CB*)ctl_cb;
70	    if (cb != NULL) {
71	        if (cb->user_data != NULL) {
72	            free(cb->user_data);
73	            cb->user_data = NULL;
74	        }
75	
76	        if (cb->msg != NULL) {
77	            if (cb->msg->data != NULL) {
78	                free(cb->msg->data);
79	                cb->msg->data = NULL;
80	            }
81	            free(cb->msg);
82	            cb->msg = NULL;
83	        }
84	
85	        free(cb);
86	        cb = NULL;
87	    }
88	}
