99	STATIC void free_current_ctl_cb(const void *item)
100	{
101	    LIST_NODE_T *node = NULL;
102	    LIST_ITER_T iter = {0};
103	    bool find = FALSE;
104	
105	    list_iter_init(g_slice_msg_list, &iter);
106	    while ((node = list_iter_next(&iter)) != NULL) {
107	        if (list_to_item(node) == item) {
108	            find = TRUE;
109	            break;
110	        }
111	    }
112	    if (find) {
113	        /* if no retry, just delete the node from pending_list */
114	        (void)list_remove_by_tag(g_slice_msg_list, item, slice_msg_cmp);
115	    }
116	
117	    list_iter_destroy(&iter);
118	
119	    return;
120	}
