122	STATIC void put_node_ctl_cb(LIST_T *list, SEND_CTL_CB *cb_head)
123	{
124	    SEND_CTL_CB *p = cb_head;
125	    SEND_CTL_CB *tmp_p = NULL;
126	
127	    while (p != NULL) {
128	        tmp_p = p->next;
129	        list_node_put(list, p->split_msg_node);
130	        p = tmp_p;
131	    }
132	}
