134	STATIC void free_send_ctl_cb(SEND_CTL_CB *cb_head)
135	{
136	    bool find = FALSE;
137	    LIST_NODE_T *node = NULL;
138	    LIST_ITER_T iter = {0};
139	    SEND_CTL_CB *p = NULL;
140	    SEND_CTL_CB *tmp_p = NULL;
141	    p = cb_head;
142	
143	    list_iter_init(g_slice_msg_list, &iter);
144	    while ((node = list_iter_next(&iter)) != NULL) {
145	        if (list_to_item(node) == cb_head) {
146	            find = TRUE;
147	            break;
148	        }
149	    }
150	
151	    if (find) {
152	        while (p != NULL) {
153	            tmp_p = p->next;
154	            free_current_ctl_cb(p);
155	            p = tmp_p;
156	        }
157	    }
158	    list_iter_destroy(&iter);
159	
160	    return;
161	}
