163	STATIC void clear_client_rsp_data(hash_table *hashtable, DM_INTF_S *intf, DM_RECV_ST *data)
164	{
165	    char property_tag[DEV_PROPERTY_TAG_LEN] = {0};
166	    char *p_property_tag = property_tag;
167	    DEV_MP_MSG_ST *tmp = NULL;
168	    int ret;
169	    DRV_CHECK_RET((hashtable != NULL));
170	    DRV_CHECK_RET((intf != NULL));
171	    DRV_CHECK_RET((data != NULL));
172	    tmp = (DEV_MP_MSG_ST *)data->msg.data;
173	    DRV_CHECK_RET((tmp != NULL));
174	    ret = sprintf_s(property_tag, sizeof(property_tag), "tag.%u.%u", tmp->op_fun, tmp->op_cmd);
175	    DRV_CHECK_RET_DO_SOMETHING((ret >= 0), DEV_MON_ERR("sprintf_s call failed! ret = %d\n", ret));
176	    hash_table_rm(hashtable, p_property_tag);
177	}
