179	STATIC DEV_MON_CLIENT_RESP_TAG_VALUE_ST *client_resp_hash_insert(hash_table *hashtable, DM_INTF_S *intf,
180	    unsigned char op_fun, unsigned char op_cmd, unsigned short data_len, unsigned char *data)
181	{
182	    char property_tag[DEV_PROPERTY_TAG_LEN] = {0};
183	    char *p_property_tag = property_tag;
184	    char *tmp_buf = NULL;
185	    DM_REP_MSG *ob = NULL;
186	    unsigned int malloc_len = 0;
187	    int ret;
188	    DEV_MON_CLIENT_RESP_TAG_VALUE_ST *value = NULL;
189	    DRV_CHECK_RETV((hashtable != NULL), NULL);
190	    DRV_CHECK_RETV((intf != NULL), NULL);
191	    DRV_CHECK_RETV((data != NULL), NULL);
192	    DRV_CHECK_RETV((data_len > 0), NULL);
193	    DRV_CHECK_RETV((data_len <= P_MAX_LENGTH), NULL);
194	
195	    ret = sprintf_s(property_tag, sizeof(property_tag), "tag.%u.%u", op_fun, op_cmd);
196	    DRV_CHECK_RETV_DO_SOMETHING((ret >= 0), NULL, DEV_MON_ERR("sprintf_s call failed! ret = %d\n", ret));
197	    value = hash_table_get(hashtable, p_property_tag);
198	    if (value != NULL) {
199	        /* if there is already data, refresh it */
200	        /* re-apply for space */
201	        DRV_CHECK_RETV((data_len > DDMP_CMD_RESP_HEAD_LEN), NULL);
202	        DRV_CHECK_RETV((value->data_len > DDMP_CMD_RESP_HEAD_LEN), NULL);
203	        malloc_len = (data_len + value->data_len - DDMP_CMD_RESP_HEAD_LEN);
204	        DRV_CHECK_RETV((malloc_len > value->data_len), NULL);
205	        tmp_buf = (char *)malloc(malloc_len);
206	        DRV_CHECK_RETV((tmp_buf != NULL), NULL);
207	        ret = memset_s((void *)tmp_buf, malloc_len, 0, malloc_len);
208	        if (ret != 0) {
209	            DEV_MON_ERR("memset_s fail: %d\n", ret);
210	            free(tmp_buf);
211	            tmp_buf = NULL;
212	            return NULL;
213	        }
214	
215	        ret = memcpy_s(tmp_buf, malloc_len, value->data, value->data_len);
216	        DRV_CHECK_RETV_DO_SOMETHING(!ret, NULL, free(tmp_buf);
217	                                    tmp_buf = NULL);
218	        ret = memcpy_s(tmp_buf + value->data_len, (size_t)(malloc_len - value->data_len), data + DDMP_CMD_RESP_HEAD_LEN,
219	                       (size_t)(data_len - DDMP_CMD_RESP_HEAD_LEN));
220	        DRV_CHECK_RETV_DO_SOMETHING(!ret, NULL, free(tmp_buf);
221	                                    tmp_buf = NULL);
222	        free(value->data);
223	        value->data = tmp_buf;
224	        value->data_len = malloc_len;
225	        /* refresh the message content */
226	        ob = (DM_REP_MSG *)value->data;
227	        ob->data_length = ((value->data_len - DDMP_CMD_RESP_HEAD_LEN) >= ob->total_length)
228	                                ? (ob->total_length)
229	                                : (value->data_len - DDMP_CMD_RESP_HEAD_LEN);
230	        return value;
231	    }
232	
233	    value = (DEV_MON_CLIENT_RESP_TAG_VALUE_ST *)malloc(sizeof(DEV_MON_CLIENT_RESP_TAG_VALUE_ST));
234	    DRV_CHECK_RETV((value != NULL), NULL);
235	    ret = memset_s((void *)value, sizeof(DEV_MON_CLIENT_RESP_TAG_VALUE_ST), 0,
236	                   sizeof(DEV_MON_CLIENT_RESP_TAG_VALUE_ST));
237	    if (ret != 0) {
238	        DEV_MON_ERR("memset_s fail: %d\n", ret);
239	        free(value);
240	        value = NULL;
241	        return NULL;
242	    }
243	
244	    value->op_fun = op_fun;
245	    value->op_cmd = op_cmd;
246	    value->data_len = data_len;
247	    value->data = (char *)malloc(data_len);
248	
249	    if (value->data == NULL) {
250	        DEV_MON_ERR("malloc failed\n");
251	        free(value);
252	        value = NULL;
253	        return NULL;
254	    }
255	
256	    ret = memset_s((void *)value->data, data_len, 0, data_len);
257	    if (ret != 0) {
258	        DEV_MON_ERR("memset_s fail: %d\n", ret);
259	        free(value->data);
260	        value->data = NULL;
261	        free(value);
262	        value = NULL;
263	        return NULL;
264	    }
265	
266	    ret = memcpy_s(value->data, data_len, data, data_len);
267	    DRV_CHECK_RETV_DO_SOMETHING(!ret, NULL, free(value->data);
268	                                value->data = NULL;
269	                                free(value);
270	                                value = NULL;
271	                                DEV_MON_ERR("memcpy_s call failed! ret:%d\n", ret));
272	    ret = hash_table_put2(hashtable, p_property_tag, value, free_client_resp_node);
273	    if (ret != 0) {
274	        DEV_MON_ERR("hash_table_put2 fail: %d\n", ret);
275	
276	        if (value->data != NULL) {
277	            free(value->data);
278	            value->data = NULL;
279	        }
280	
281	        free(value);
282	        value = NULL;
283	        return NULL;
284	    }
285	
286	    return value;
287	}
