289	STATIC void comm_msg_handle(DM_INTF_S *intf, DM_RECV_ST *recv, const void *user_data, int data_len)
290	{
291	    int ret;
292	    int find = 0;
293	    DM_REP_MSG *ob = NULL;
294	    SEND_CTL_CB *p = NULL;
295	    SEND_CTL_CB *tmp_p = NULL;
296	    LIST_NODE_T *node = NULL;
297	    LIST_ITER_T iter = {0};
298	
299	    (void)data_len;
300	    DRV_CHECK_RET((intf != NULL));
301	    DRV_CHECK_RET((recv != NULL));
302	    DRV_CHECK_RET((user_data != NULL));
303	    ret = memcpy_s(&p, sizeof(SEND_CTL_CB *), user_data, sizeof(SEND_CTL_CB *));
304	    DRV_CHECK_RET_DO_SOMETHING(!ret, DEV_MON_ERR("memcpy_s call failed! ret:%d\n", ret));
305	    DRV_CHECK_RET((p != NULL));
306	
307	    list_iter_init(g_slice_msg_list, &iter);
308	    while ((node = list_iter_next(&iter)) != NULL) {
309	        if (list_to_item(node) == p) {
310	            find = 1;
311	            break;
312	        }
313	    }
314	
315	    if (!find) {
316	        /* if no find */
317	        list_iter_destroy(&iter);
318	        return;
319	    }
320	
321	    /* Check the return value; if it is not a success message, directly call the callback function to return,
322	       and release the command list and any existing responses */
323	    ob = (DM_REP_MSG *)recv->msg.data;
324	    DRV_CHECK_RET_DO_SOMETHING((ob != NULL), free_send_ctl_cb(p));
325	    DRV_CHECK_RET_DO_SOMETHING((recv->msg.data_len >= DDMP_CMD_RESP_HEAD_LEN), free_send_ctl_cb(p));
326	
327	    if (ob->err_code != 0) {
328	        if (p->rsp_hndl != NULL) {
329	            p->rsp_hndl(intf, recv, p->user_data, p->data_len);
330	        }
331	
332	        free_send_ctl_cb(p);
333	        p = NULL;
334	        clear_client_rsp_data(g_client_rsp_hashtable, intf, recv);
335	        goto iter_destory;
336	    }
337	
338	    if (p->next == NULL) { /* the last frame, call the user's callback function */
339	        /* Confirm whether all messages have been received.
340	           If some messages are not fully received, resend the messages and update the offset */
341	        ret = dmp_msg_recv_resp(intf, recv, p);
342	        if (ret != 0) {
343	            DEV_MON_ERR("send request failed\n");
344	            free_send_ctl_cb(p);
345	            p = NULL;
346	        }
347	        goto iter_destory;
348	    } else {
349	        tmp_p = p->next;
350	        free_current_ctl_cb(p);
351	        ret = dm_send_req(tmp_p->intf, &tmp_p->addr, tmp_p->addr_len, tmp_p->msg,
352	                          (DM_MSG_CMD_HNDL_T)comm_msg_handle, &tmp_p, sizeof(SEND_CTL_CB *));
353	        if (ret != 0) {
354	            DEV_MON_ERR("send request failed\n");
355	            free_send_ctl_cb(tmp_p);
356	            tmp_p = NULL;
357	        }
358	    }
359	
360	iter_destory:
361	    list_iter_destroy(&iter);
362	    return;
363	}
