365	int dmp_msg_recv_resp(DM_INTF_S *intf, DM_RECV_ST *recv, SEND_CTL_CB *ctl)
366	{
367	    DM_REP_MSG *ob = NULL;
368	    DEV_MP_MSG_ST *req = NULL;
369	    signed int ret = 0;
370	    unsigned char *tmp_recv = NULL;
371	    DM_SMBUS_ADDR_ST *addr = NULL;
372	    DEV_MON_CLIENT_RESP_TAG_VALUE_ST *value = NULL;
373	    DRV_CHECK_RETV((intf != NULL), FAILED);
374	    DRV_CHECK_RETV((recv != NULL), FAILED);
375	    DRV_CHECK_RETV((ctl != NULL), FAILED);
376	    addr = (DM_SMBUS_ADDR_ST *)recv->addr;
377	    DRV_CHECK_RETV((addr != NULL), FAILED);
378	
379	    if ((addr->addr_type == DM_SMBUS_ADDR_TYPE) && (addr->channel == DM_SMBUS_CHANNEL)) {
380	        if (ctl->rsp_hndl != NULL) {
381	            ctl->rsp_hndl(intf, recv, ctl->user_data, ctl->data_len);
382	        }
383	        free_send_ctl_cb(ctl);
384	        return OK;
385	    }
386	
387	    ob = (DM_REP_MSG *)recv->msg.data;
388	    DRV_CHECK_RETV((ob != NULL), FAILED);
389	    DRV_CHECK_RETV((recv->msg.data_len >= DDMP_CMD_RESP_HEAD_LEN), FAILED);
390	    value = client_resp_hash_insert(g_client_rsp_hashtable, intf, ob->op_fun, ob->op_cmd, recv->msg.data_len,
391	                                    recv->msg.data);
392	    if (value == NULL) {
393	        return FAILED;
394	    }
395	
396	    if (ob->total_length > DM_MSG_DATA_MAX) {
397	        DEV_MON_ERR("ob total_length illegal!total_length:%u\n", ob->total_length);
398	        clear_client_rsp_data(g_client_rsp_hashtable, intf, recv);
399	        return FAILED;
400	    }
401	
402	    if (value->data_len == (ob->total_length + DDMP_CMD_RESP_HEAD_LEN)) { /* the data has been collected */
403	        /* reorganization news */
404	        tmp_recv = recv->msg.data;
405	        recv->msg.data = (unsigned char *)malloc((size_t)value->data_len);
406	
407	        if (recv->msg.data == NULL) {
408	            recv->msg.data = tmp_recv;
409	            DEV_MON_ERR("malloc recv msg data fail!\n");
410	            clear_client_rsp_data(g_client_rsp_hashtable, intf, recv);
411	            return FAILED;
412	        }
413	
414	        ret = memset_s((void *)recv->msg.data, value->data_len, 0, value->data_len);
415	        if (ret != 0) {
416	            DEV_MON_ERR("memset_s fail: %d\n", ret);
417	            clear_client_rsp_data(g_client_rsp_hashtable, intf, recv);
418	            free(recv->msg.data);
419	            recv->msg.data = NULL;
420	            return ret;
421	        }
422	
423	        ret = memcpy_s(recv->msg.data, value->data_len, value->data, value->data_len);
424	        DRV_CHECK_RETV_DO_SOMETHING(!ret, FAILED, free(recv->msg.data);
425	                                    recv->msg.data = tmp_recv;
426	                                    clear_client_rsp_data(g_client_rsp_hashtable, intf, recv));
427	        recv->msg.data_len = (unsigned short)value->data_len;
428	        ob = (DM_REP_MSG *)recv->msg.data;
429	        ob->data_length = (value->data_len - DDMP_CMD_RESP_HEAD_LEN);
430	        clear_client_rsp_data(g_client_rsp_hashtable, intf, recv);
431	        ctl->rsp_hndl(intf, recv, ctl->user_data, ctl->data_len);
432	        free(recv->msg.data);
433	        recv->msg.data = NULL;
434	        free_current_ctl_cb(ctl);
435	        recv->msg.data = tmp_recv;
436	        return OK;
437	    } else if (value->data_len > (ob->total_length + DDMP_CMD_RESP_HEAD_LEN)) {
438	        DEV_MON_ERR("value data_len illegal!data len:%u, total len:%u!\n", value->data_len, ob->total_length);
439	        clear_client_rsp_data(g_client_rsp_hashtable, intf, recv);
440	        return FAILED;
441	    } else {
442	        /* modify the request message offset and resend it */
443	        req = (DEV_MP_MSG_ST *)ctl->msg->data;
444	        DRV_CHECK_RETV_DO_SOMETHING((req != NULL), FAILED, clear_client_rsp_data(g_client_rsp_hashtable, intf, recv));
445	        DRV_CHECK_RETV_DO_SOMETHING((value->data_len > DDMP_CMD_RESP_HEAD_LEN),
446	            FAILED, clear_client_rsp_data(g_client_rsp_hashtable, intf, recv));
447	        DRV_CHECK_RETV_DO_SOMETHING((intf->max_trans_len > DDMP_CMD_RESP_HEAD_LEN),
448	            FAILED, clear_client_rsp_data(g_client_rsp_hashtable, intf, recv));
449	        req->offset = (value->data_len - DDMP_CMD_RESP_HEAD_LEN);
450	        req->length = (intf->max_trans_len - DDMP_CMD_RESP_HEAD_LEN);
451	        ret = dm_send_req(ctl->intf, &ctl->addr, ctl->addr_len, ctl->msg,
452	                          (DM_MSG_CMD_HNDL_T)comm_msg_handle, &ctl, sizeof(SEND_CTL_CB *));
453	        if (ret != 0) {
454	            DEV_MON_ERR("send request failed\n");
455	            clear_client_rsp_data(g_client_rsp_hashtable, intf, recv);
456	            return FAILED;
457	        }
458	
459	        return OK;
460	    }
461	}
