463	STATIC SEND_CTL_CB *malloc_new_slice_msg(DM_INTF_S *intf)
464	{
465	    int ret;
466	    SEND_CTL_CB *cb_head = NULL;
467	
468	    cb_head = (SEND_CTL_CB *)malloc(sizeof(SEND_CTL_CB));
469	    if (cb_head == NULL) {
470	        return NULL;
471	    }
472	
473	    ret = memset_s((void *)cb_head, sizeof(SEND_CTL_CB), 0, sizeof(SEND_CTL_CB));
474	    DRV_CHECK_GOTO((!ret), free_cb_head);
475	
476	    cb_head->msg = (DM_MSG_ST *)malloc(sizeof(DM_MSG_ST));
477	    DRV_CHECK_GOTO((cb_head->msg != NULL), free_cb_head);
478	
479	    ret = memset_s((void *)cb_head->msg, sizeof(DM_MSG_ST), 0, sizeof(DM_MSG_ST));
480	    DRV_CHECK_GOTO(!ret, free_msg);
481	
482	    cb_head->msg->data = (unsigned char *)malloc(intf->max_trans_len);
483	    DRV_CHECK_GOTO((cb_head->msg->data != NULL), free_msg);
484	
485	    ret = memset_s((void *)cb_head->msg->data, intf->max_trans_len, 0, intf->max_trans_len);
486	    DRV_CHECK_GOTO(!ret, free_data);
487	
488	    return cb_head;
489	
490	free_data:
491	    free(cb_head->msg->data);
492	free_msg:
493	    free(cb_head->msg);
494	free_cb_head:
495	    free(cb_head);
496	    return NULL;
497	}
