499	STATIC SEND_CTL_CB *slice_msg(DM_INTF_S *intf, const DM_ADDR_ST *addr, unsigned int addr_len, const DM_MSG_ST *msg,
500	    DM_MSG_CMD_HNDL_T rsp_hndl, const void *user_data, int data_len)
501	{
502	    int ret;
503	    unsigned int i;
504	    unsigned int count = 0;
505	    SEND_CTL_CB *cb_head = NULL;
506	    SEND_CTL_CB *tmp_cb = NULL;
507	    SEND_CTL_CB *p = NULL;
508	    DEV_MP_MSG_ST *data = NULL;
509	    unsigned int new_data_len = 0;
510	    DRV_CHECK_RETV((intf != NULL), NULL);
511	    DRV_CHECK_RETV((addr != NULL), NULL);
512	    DRV_CHECK_RETV((msg != NULL), NULL);
513	    DRV_CHECK_RETV((intf->max_trans_len > DEV_MON_REQUEST_HEAD_LEN), NULL);
514	
515	    if (msg->data_len <= intf->max_trans_len) { /* no subcontracting required; directly call the sending interface */
516	        new_data_len = *(unsigned int *)(msg->data + 8);
517	        count = 1;
518	    } else {
519	        new_data_len = (intf->max_trans_len - DEV_MON_REQUEST_HEAD_LEN);
520	        DRV_CHECK_RETV((new_data_len <= (unsigned int)USHRT_MAX), NULL);
521	        count = (msg->data_len - DEV_MON_REQUEST_HEAD_LEN - 1U) / (unsigned short)(new_data_len);
522	        count++;
523	        DEV_MON_INFO("slice msg. (msg->data_len=%d; count=%d)\n", msg->data_len, count);
524	    }
525	
526	    cb_head = malloc_new_slice_msg(intf);
527	    DRV_CHECK_RETV((cb_head != NULL), NULL);
528	
529	    ret = list_append_get_node(g_slice_msg_list, cb_head, &cb_head->split_msg_node);
530	    if (ret != 0) {
531	        slice_msg_free(cb_head);
532	        return NULL;
533	    }
534	
535	    SET_CTL_CB(cb_head, ret, intf, addr, addr_len, rsp_hndl, user_data, data_len);
536	    DRV_CHECK_GOTO(!ret, error_out);
537	
538	    ret = memcpy_s(cb_head->msg->data, intf->max_trans_len, msg->data,
539	                   ((msg->data_len <= intf->max_trans_len) ? msg->data_len : intf->max_trans_len));
540	    DRV_CHECK_GOTO(!ret, error_out);
541	
542	    cb_head->next = NULL;
543	    cb_head->msg->data_len = (msg->data_len <= (unsigned short)intf->max_trans_len) ? msg->data_len : (unsigned short)intf->max_trans_len;
544	    data = (DEV_MP_MSG_ST *)cb_head->msg->data;
545	
546	    /* modify request data content */
547	    if (msg->data_len <= intf->max_trans_len) {
548	        SET_BIT((data->lun), 7);
549	    } else {
550	        CLR_BIT((data->lun), 7);
551	        data->offset = 0;
552	        data->length = new_data_len;
553	    }
554	    p = cb_head;
555	
556	    for (i = 1; i < count; i++) {
557	        tmp_cb = malloc_new_slice_msg(intf);
558	        DRV_CHECK_GOTO((tmp_cb != NULL), error_out);
559	
560	        ret = list_append_get_node(g_slice_msg_list, tmp_cb, &tmp_cb->split_msg_node);
561	        if (ret != 0) {
562	            slice_msg_free(tmp_cb);
563	            goto error_out;
564	        }
565	
566	        p->next = tmp_cb;
567	        SET_CTL_CB(tmp_cb, ret, intf, addr, addr_len, rsp_hndl, user_data, data_len);
568	        DRV_CHECK_GOTO(!ret, error_out);
569	
570	        /* copy head */
571	        ret = memcpy_s(tmp_cb->msg->data, intf->max_trans_len, msg->data, DEV_MON_REQUEST_HEAD_LEN);
572	        DRV_CHECK_GOTO(!ret, error_out);
573	
574	        if (i != (count - 1)) {
575	            ret = memcpy_s((unsigned char *)(tmp_cb->msg->data + DEV_MON_REQUEST_HEAD_LEN),
576	                           intf->max_trans_len - DEV_MON_REQUEST_HEAD_LEN,
577	                           (unsigned char *)(msg->data + DEV_MON_REQUEST_HEAD_LEN + (unsigned short)(i * new_data_len)),
578	                           new_data_len);
579	            DRV_CHECK_GOTO(!ret, error_out);
580	            tmp_cb->msg->data_len = (short unsigned int)intf->max_trans_len;
581	            data = (DEV_MP_MSG_ST *)tmp_cb->msg->data;
582	            /* modify request data content */
583	            CLR_BIT((data->lun), 7);
584	            data->offset = (i * new_data_len);
585	            data->length = new_data_len;
586	        } else {
587	            ret =
588	                memcpy_s(((unsigned char *)(tmp_cb->msg->data + DEV_MON_REQUEST_HEAD_LEN)),
589	                         intf->max_trans_len - DEV_MON_REQUEST_HEAD_LEN,
590	                         ((unsigned char *)(msg->data + DEV_MON_REQUEST_HEAD_LEN + (unsigned short)(i * new_data_len))),
591	                         (msg->data_len - DEV_MON_REQUEST_HEAD_LEN - (unsigned short)(i * new_data_len)));
592	            DRV_CHECK_GOTO(!ret, error_out);
593	            tmp_cb->msg->data_len = (unsigned short)(msg->data_len - (unsigned short)(i * new_data_len));
594	            data = (DEV_MP_MSG_ST *)tmp_cb->msg->data;
595	            /* modify request data content */
596	            SET_BIT((data->lun), 7);
597	            data->offset = (i * new_data_len);
598	            data->length = (tmp_cb->msg->data_len - DEV_MON_REQUEST_HEAD_LEN);
599	            break;
600	        }
601	
602	        tmp_cb->next = NULL;
603	        tmp_cb->msg->data_len = (unsigned short)intf->max_trans_len;
604	        p = tmp_cb;
605	    }
606	    return cb_head;
607	error_out:
608	    put_node_ctl_cb(g_slice_msg_list, cb_head);
609	    free_send_ctl_cb(cb_head);
610	    cb_head = NULL;
611	    return NULL;
612	}
613	
614	int slice_msg_list_init(void)
615	{
616	    int ret;
617	
618	    if (g_slice_msg_list != NULL) {
619	        DEV_MON_WARNING("g_slice_msg_list already init.");
620	        return 0;
621	    }
622	
623	    ret = list_create(&g_slice_msg_list, slice_msg_cmp, slice_msg_free);
624	    if (ret != 0) {
625	        DEV_MON_ERR("create g_slice_msg_list fail,ret:%d\r\n", ret);
626	        return ret;
627	    }
628	
629	    return 0;
630	}
631	
632	void slice_msg_list_uninit(void)
633	{
634	    if (g_slice_msg_list != NULL) {
635	        list_destroy(g_slice_msg_list);
636	    }
637	    g_slice_msg_list = NULL;
638	}
639	
640	int client_rsp_hashtable_init(void)
641	{
642	    if (g_client_rsp_hashtable != NULL) {
643	        DEV_MON_WARNING("g_client_rsp_hashtable already init.");
644	        return 0;
645	    }
646	
647	    g_client_rsp_hashtable = hash_table_new();
648	    if (g_client_rsp_hashtable == NULL) {
649	        DEV_MON_ERR("create g_client_rsp_hashtable fail.");
650	        return FAILED;
651	    }
652	    return 0;
653	}
654	
655	void client_rsp_hashtable_uninit(void)
656	{
657	    if (g_client_rsp_hashtable != NULL) {
658	        hash_table_delete(g_client_rsp_hashtable);
659	        g_client_rsp_hashtable = NULL;
660	    }
661	}
662	
663	int dev_mon_send_request(DM_INTF_S *intf, DM_ADDR_ST *addr, unsigned int addr_len, const DM_MSG_ST *msg,
664	                         DM_MSG_CMD_HNDL_T rsp_hndl, const void *user_data, int data_len)
665	{
666	    int ret;
667	    SEND_CTL_CB *cb_head = NULL;
668	    DRV_CHECK_RETV((intf != NULL), DRV_ERROR_PARA_ERROR);
669	    DRV_CHECK_RETV((addr != NULL), DRV_ERROR_PARA_ERROR);
670	    DRV_CHECK_RETV((msg != NULL), DRV_ERROR_PARA_ERROR);
671	    cb_head = slice_msg(intf, addr, addr_len, msg, rsp_hndl, user_data, data_len);
672	    if (cb_head == NULL) {
673	        DEV_MON_ERR("slice_msg return NULL pointer\n");
674	        return DRV_ERROR_PARA_ERROR;
675	    }
676	
677	    ret = dm_send_req(cb_head->intf, addr, cb_head->addr_len, cb_head->msg,
678	        (DM_MSG_CMD_HNDL_T)comm_msg_handle, &cb_head, sizeof(SEND_CTL_CB *));
679	    put_node_ctl_cb(g_slice_msg_list, cb_head);
680	    if (ret != 0) {
681	        free_send_ctl_cb(cb_head);
682	        return ret;
683	    }
684	    return ret;
685	}
