175	    DRV_CHECK_RETV(session, FAILED);
176	    chan_cb = (DM_HDC_CB_ST *)(intf->channel_cb);
177	    DRV_CHECK_RETV(chan_cb, FAILED);
178	
179	    ret = __dm_session_hdc_recv_proc(session, &p_rcvmsg, &p_rcvbuf, &buf_len);
180	    if (ret != 0) {
181	        DEV_MON_ERR("hdc recv error %d \n", ret);
182	        return ret;
183	    }
184	
185	    /* write data to pipe */
186	    hdc_msg = (HDC_MSG_ST *)p_rcvbuf;
187	    if (hdc_msg == NULL) {
188	        ret = FAILED;
189	        DEV_MON_ERR("p_rcvbuf is NULL\n");
190	        goto out;
191	    }
192	
193	    if (hdc_msg->data_len > DM_MSG_DATA_MAX) {
194	        ret = FAILED;
195	        DEV_MON_ERR("hdc_msg->data_len %d is invalid, max len %d\n", hdc_msg->data_len, DM_MSG_DATA_MAX);
196	        goto out;
197	    }
198	    hdc_msg->session = (unsigned long long)(uintptr_t)session;
199	    msg.data = (unsigned char *)p_rcvbuf;
200	    msg.data_len = (unsigned short)buf_len;
201	
202	    if (msg.data_len > sizeof(HDC_MSG_ST)) {
203	        ret = FAILED;
204	        DEV_MON_ERR("msg.data_len %u is invalid, max len %u\n", msg.data_len, sizeof(HDC_MSG_ST));
205	        goto out;
206	    }
207	    ret = __hdc_write_to_pipe(intf, msg_type, session, &msg, (signed long)(uintptr_t)&p_rcvbuf);
208	
209	out:
210	    (void)drvHdcFreeMsg(p_rcvmsg);
211	    p_rcvmsg = NULL;
212	
213	    return ret;
214	}
