216	STATIC int g_hdc_thread_num = 0;
217	#define HDC_ACCEPT_THREAD_MAX 1024
218	#define HDC_THREAD_WAIT_INTERVAL (10 * 1000)
219	#define HDC_THREAD_WAIT_LOG_CNT 500
220	STATIC void hdc_thread_num_limit(void)
221	{
222	    unsigned int log_cnt = 0;
223	
224	    while (g_hdc_thread_num >= HDC_ACCEPT_THREAD_MAX) {
225	        if (log_cnt % HDC_THREAD_WAIT_LOG_CNT == 0) {
226	            DEV_MON_WARNING("HDC thread_num exceed limit, (thread_num=%d)\n", g_hdc_thread_num);
227	        }
228	        log_cnt++;
229	        (void)usleep(HDC_THREAD_WAIT_INTERVAL);
230	    }
231	    if (log_cnt > 0) {
232	        DEV_MON_INFO("HDC thread_num recover, (thread_num=%d)\n", g_hdc_thread_num);
233	    }
234	}
