236	STATIC void *__dm_server_recv_msg_proc(void *arg)
237	{
238	    int ret;
239	    HDC_SESSION session = NULL;
240	    DM_INTF_S* intf = NULL;
241	    RECV_MSG_ST *recv_msg = NULL;
242	
243	    (void)prctl(PR_SET_NAME, "server_recv_msg_proc");
244	
245	    if (arg == NULL) {
246	        DEV_MON_ERR("input arg is NULL\n");
247	        return NULL;
248	    }
249	
250	    recv_msg = (RECV_MSG_ST *)arg;
251	    session = recv_msg->session;
252	    intf = recv_msg->intf;
253	    (void)drvHdcSetSessionReference(session);
254	    ret = __dm_session_recv_proc(intf, session, REQUEST_MSG);
255	    if (ret != 0) {
256	        if (ret != EAGAIN) {
257	            DEV_MON_ERR("Session processing failed. (ret=%d)\n", ret);
258	        }
259	        (void)drvHdcSessionClose(session);
260	    }
261	
262	    free(recv_msg);
