268	STATIC void *__dm_server_accept_proc(void *arg)
269	{
270	    HDC_SESSION session = NULL;
271	    HDC_SERVER server = NULL;
272	    DM_INTF_S *intf = NULL;
273	    DM_HDC_CB_ST *chan_cb = NULL;
274	    int ret;
275	    pthread_t server_thread;
276	    pthread_attr_t attr = {{0}};
277	    RECV_MSG_ST *recv_msg_proc_st = NULL;
278	
279	    intf = (DM_INTF_S *)arg;
280	    chan_cb = (DM_HDC_CB_ST *)(intf->channel_cb);
281	    server = (HDC_SERVER)chan_cb->cb;
282	
283	    (void)mmSetCurrentThreadName("server_accept");
284	
285	    while (g_dm_hdc_run != 0) {
286	        ret = drvHdcSessionAccept(server, &session);
287	        if (ret != OK) {
288	            (void)usleep(1000); // 1000 sleep 1ms
289	            continue;
290	        }
291	
292	        recv_msg_proc_st = malloc(sizeof(RECV_MSG_ST));
293	        if (recv_msg_proc_st == NULL) {
294	            (void)drvHdcSessionClose(session);
295	            continue;
296	        }
297	
298	        /* the pointer recv_msg_proc_st get value below, so not need memset */
299	        recv_msg_proc_st->intf = intf;
300	        recv_msg_proc_st->session = session;
301	        (void)pthread_attr_init(&attr);
302	        (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
303	        (void)pthread_attr_setstacksize(&attr, DEV_MON_ROOT_STACK_SIZE);
304	
305	        if ((pthread_create(&server_thread, &attr, __dm_server_recv_msg_proc, (void*)recv_msg_proc_st) != 0)) {
306	            DEV_MON_ERR("pthread_create fail errno=%d:%s\n", errno, strerror(errno));
307	            (void)drvHdcSessionClose(session);
308	            (void)pthread_attr_destroy(&attr);
309	            free(recv_msg_proc_st);
310	            recv_msg_proc_st = NULL;
311	            (void)usleep(1000); // 1000 sleep 1ms
312	            continue;
313	        }
314	        (void)pthread_attr_destroy(&attr);
315	        __sync_fetch_and_add(&g_hdc_thread_num, 1);
316	        hdc_thread_num_limit();
317	    }
318	
319	    return NULL;
320	}
