322	#define DM_HDC_FD_NUM 2
323	STATIC int __dm_hdc_open(DM_INTF_S *intf)
324	{
325	    int fds[DM_HDC_FD_NUM] = {0};
326	    HDC_CLIENT client = NULL;
327	    HDC_SERVER server = NULL;
328	    DM_HDC_CB_ST *chan_cb = NULL;
329	    int ret;
330	    unsigned int retry_times = 0;
331	    DM_HDC_ADDR_ST *myaddr = NULL;
332	    pthread_t server_thread;
333	    mmThreadAttr thread_attr = {0};
334	    mmThread *thread_handle = {0};
335	    mmUserBlock_t func_block = {0};
336	
337	    if ((pipe(fds) < 0) || (fcntl(fds[0], F_SETFL, O_NONBLOCK) < 0) || (fcntl(fds[1], F_SETFL, O_NONBLOCK) < 0) ||
338	        (fcntl(fds[0], F_SETFD, FD_CLOEXEC) < 0) || (fcntl(fds[1], F_SETFD, FD_CLOEXEC) < 0)) {
339	        return errno;
340	    }
341	
342	    intf->rfd = fds[0];
343	    intf->wfd = fds[1];
344	    intf->channel_cb = malloc(sizeof(DM_HDC_CB_ST));
345	    DRV_CHECK_RETV((intf->channel_cb != NULL), -ENOMEM);
346	    ret = memset_s((void *)intf->channel_cb, sizeof(DM_HDC_CB_ST), 0, sizeof(DM_HDC_CB_ST));
347	    if (ret != 0) {
348	        DEV_MON_ERR("memset_s fail: %d\n", ret);
349	        free(intf->channel_cb);
350	        intf->channel_cb = NULL;
351	        return ret;
352	    }
353	
354	    myaddr = (DM_HDC_ADDR_ST *)&(intf->my_addr);
355	    chan_cb = (DM_HDC_CB_ST *)(intf->channel_cb);
356	    chan_cb->cb = NULL;
357	
358	    if (!myaddr->hdc_type) {
359	        ret = drvHdcClientCreate(&client, MAX_HDC_CLIENT, HDC_SERVICE_TYPE_DMP, 0);
360	        if (ret != OK) {
361	            DEV_MON_ERR("%s%d%s%d\n", __FUNCTION__, __LINE__, "error=", ret);
362	            free(intf->channel_cb);
363	            intf->channel_cb = NULL;
364	            return ret;
365	        }
366	
367	        chan_cb->cb = (void *)client;
368	    } else {
369	    retry:
370	        ret = drvHdcServerCreate(myaddr->dev_id, HDC_SERVICE_TYPE_DMP, &server);
371	        if (ret != OK) {
372	            if (retry_times++ > DM_HDC_RETRY_TIMES) {
373	                free(intf->channel_cb);
374	                intf->channel_cb = NULL;
375	                DEV_MON_ERR("drvHdcServerCreate failed,%s%d%s%d\n", __FUNCTION__, __LINE__, "error=", ret);
376	                return ret;
377	            } else {
378	                (void)sleep(DM_HDC_RETRY_TIMEDELAY);
379	                goto retry;
380	            }
381	        }
382	
383	        chan_cb->cb = (void *)server;
384	
385	        thread_attr.stackFlag = TRUE;
386	        thread_attr.detachFlag = TRUE;
387	        thread_attr.stackSize = DEV_MON_ROOT_STACK_SIZE;
388	        thread_handle = &server_thread;
389	        func_block.procFunc = __dm_server_accept_proc;
390	        func_block.pulArg = (void *)intf;
391	
392	        ret = mmCreateTaskWithThreadAttr(thread_handle, &func_block, &thread_attr);
393	        if (ret != 0) {
394	            DEV_MON_ERR("pthread_create error,ret = %d,errno=%d:%s\n", ret, errno, strerror(errno));
395	            (void)drvHdcServerDestroy(server);
396	            ret = mmSleep(1);
397	            DRV_CHECK_STR(ret == 0);
398	            free(intf->channel_cb);
399	            intf->channel_cb = NULL;
400	            return -1;
401	        }
402	    }
403	
404	    return 0;
405	}
