407	STATIC int dm_hdc_session_connect(int peer_node, int peer_devid, HDC_CLIENT client, HDC_SESSION *session)
408	{
409	    unsigned int dmp_started = false;
410	    int retry_i = 0;
411	    int retry_j = 0;
412	    int ret;
413	    (void)peer_node;
414	
415	    ret = drvGetDmpStarted((uint32_t)peer_devid, &dmp_started);
416	    if (ret != OK) {
417	        DEV_MON_ERR("%s %d err, devid %d ret %d, dmp_started %u\n", __FUNCTION__, __LINE__,
418	                    peer_devid, ret, dmp_started);
419	        return DRV_ERROR_DEVICE_NOT_READY;
420	    }
421	
422	retry:
423	    ret = drvHdcSessionConnect(0, peer_devid, client, session);
424	    /* need to retry when Session connection not listen */
425	    if ((ret == DRV_ERROR_REMOTE_NOT_LISTEN || ret == DRV_ERROR_DEVICE_NOT_READY) &&
426	        (dmp_started == false) && (retry_i < DMHDC_CLIENT_SEND_RETRYTIME)) {
427	        retry_i++;
428	        (void)sleep(1);
429	        goto retry;
430	    } else if ((ret == DRV_ERROR_REMOTE_NO_SESSION) && (retry_j < DMHDC_CLIENT_SEND_NO_SESSION_RETRYTIME)) {
431	        retry_j++;
432	        (void)usleep(1000); /* 1000 sleep 1ms */
433	        goto retry;
434	    }
435	    if (ret != OK) {
436	        DEV_MON_ERR("%s %d failed.(dev_id=%d ret=%d, retry_i=%d, retry_j=%d)\n", __FUNCTION__, __LINE__,
437	                    peer_devid, ret, retry_i, retry_j);
438	        return ret;
439	    }
440	    return ret;
441	}
