443	STATIC int dm_hdc_send_msg(const DM_ADDR_ST *addr, DM_INTF_S *intf, const DM_MSG_ST *msg,
444	    DM_MSG_TYPE msg_type, signed long msgid, HDC_SESSION session)
445	{
446	    HDC_MSG_ST *hdc_msg = NULL;
447	    struct drvHdcMsg *p_msg_snd = NULL;
448	    const DM_HDC_ADDR_ST *dstaddr = (const DM_HDC_ADDR_ST *)addr;
449	    DM_HDC_ADDR_ST *myaddr = (DM_HDC_ADDR_ST *)&(intf->my_addr);
450	    int retry_times = 0;
451	    int ret;
452	
453	    hdc_msg = (HDC_MSG_ST *)malloc(sizeof(HDC_MSG_ST));
454	    DRV_CHECK_RETV_DO_SOMETHING((hdc_msg != NULL), DRV_ERROR_NO_RESOURCES, DEV_MON_ERR("msg malloc err\n"));
455	    ret = __format_hdc_msg(hdc_msg, dstaddr, myaddr, msg, msgid);
456	    if (ret != 0) {
457	        DEV_MON_ERR("hdc msg format failed, (ret=%d)\n", ret);
458	        goto FREE_HDC_MSG;
459	    }
460	    (void)drvHdcSetSessionReference(session);
461	    hdc_msg->session = (unsigned long long)(uintptr_t)session;
462	    hdc_msg->msg_type = msg_type;
463	
464	    ret = drvHdcAllocMsg(session, &p_msg_snd, 1);
465	    if (ret != OK) {
466	        DEV_MON_ERR("%s %d alloc msg err. (ret=%d)\n", __FUNCTION__, __LINE__, ret);
467	        goto FREE_HDC_MSG;
468	    }
469	
470	    ret = drvHdcAddMsgBuffer(p_msg_snd, (char *)hdc_msg, (int)(HDCMSG_HEAD_SIZE + hdc_msg->data_len));
471	    if (ret != OK) {
472	        DEV_MON_ERR("%s %d add msg err, ret %d\n", __FUNCTION__, __LINE__, ret);
473	        goto FREE_MSG_SND;
474	    }
475	
476	    while (retry_times < DMHDC_CLIENT_SEND_TIMEOUT_RETRY_TIMES) {
477	        ret = halHdcSend(session, p_msg_snd, HDC_FLAG_WAIT_TIMEOUT, HDC_MSG_TIMEOUT);
478	        if (ret == DRV_ERROR_WAIT_TIMEOUT) {
479	            DEV_MON_INFO("halHdcSend timeout. (ret=%d; retry_count=%d)\n", ret, retry_times);
480	            retry_times++;
481	            continue;
482	        }
483	        break;
484	    }
485	    if (ret != OK) {
486	        DEV_MON_ERR("Sending message was abnormal. (func=\"%s\"; line=%d; retry_count=%d; ret=%d)\n",
487	                    __FUNCTION__, __LINE__, retry_times, ret);
488	        goto FREE_MSG_SND;
489	    }
490	
491	FREE_MSG_SND:
492	    (void)drvHdcFreeMsg(p_msg_snd);
493	    p_msg_snd = NULL;
494	FREE_HDC_MSG:
495	    free(hdc_msg);
496	    hdc_msg = NULL;
497	    return ret;
498	}
