500	STATIC int __dm_hdc_client_send(DM_INTF_S *intf, DM_MSG_TYPE msg_type, const DM_ADDR_ST *addr, unsigned int addr_len,
501	                                const DM_MSG_ST *msg, signed long msgid)
502	{
503	    int ret;
504	    HDC_SESSION session = NULL;
505	    DM_HDC_CB_ST *chan_cb = intf->channel_cb;
506	    const DM_HDC_ADDR_ST *dstaddr = (const DM_HDC_ADDR_ST *)addr;
507	    (void)addr_len;
508	
509	    ret = dm_hdc_session_connect(0, dstaddr->peer_devid, (HDC_CLIENT)(chan_cb->cb), &session);
510	    if (ret != 0) {
511	        DEV_MON_ERR("dm_hdc_session_connect failed. (dev_id=%d; ret=%d)\n", dstaddr->peer_devid, ret);
512	        return ret;
513	    }
514	
515	    ret = dm_hdc_send_msg(addr, intf, msg, msg_type, msgid, session);
516	    if (ret != 0) {
517	        DEV_MON_ERR("dm_hdc_send_msg failed. (dev_id=%d; ret=%d)\n", dstaddr->peer_devid, ret);
518	        (void)drvHdcSessionClose(session);
519	        return ret;
520	    }
521	
522	    ret = __dm_session_recv_proc(intf, session, msg_type);
523	    if (ret != 0) {
524	        DEV_MON_ERR("__dm_session_recv_proc failed. (ret=%d)\n", ret);
525	        (void)drvHdcSessionClose(session);
526	        return ret;
527	    }
528	
529	    (void)drvHdcSessionClose(session);
530	    return 0;
531	}
