533	STATIC int __dm_hdc_server_send(DM_INTF_S *intf, DM_MSG_TYPE msg_type, DM_ADDR_ST *addr, unsigned int addr_len,
534	                                const DM_MSG_ST *msg, signed long msgid)
535	{
536	    int ret;
537	    HDC_SESSION session = NULL;
538	    struct drvHdcMsg *p_msg_snd = NULL;
539	    DM_HDC_ADDR_ST *dstaddr = NULL;
540	    DM_HDC_ADDR_ST *myaddr = NULL;
541	    HDC_MSG_ST *hdc_msg = NULL;
542	    (void)addr_len;
543	
544	    dstaddr = (DM_HDC_ADDR_ST *)addr;
545	    myaddr = (DM_HDC_ADDR_ST *)&(intf->my_addr);
546	    session = (HDC_SESSION)(uintptr_t)dstaddr->session;
547	
548	    if (dstaddr->hdc_work_status == HDC_ADDR_CLOSE) {
549	        DEV_MON_WARNING("__dm_hdc_server_send: session already close. hdc_status_status = %d\n",
550	            dstaddr->hdc_work_status);
551	        return DRV_ERROR_INNER_ERR;
552	    }
553	
554	    hdc_msg = (HDC_MSG_ST *)calloc(1, sizeof(HDC_MSG_ST));
555	    if (hdc_msg == NULL) {
556	        DEV_MON_ERR("__dm_hdc_server_send: malloc fail.errno=%d\n", errno);
557	        (void)drvHdcSessionClose(session);
558	        dstaddr->hdc_work_status = HDC_ADDR_CLOSE;
559	        return DRV_ERROR_INNER_ERR;
560	    }
561	
562	    ret = __format_hdc_msg(hdc_msg, dstaddr, myaddr, msg, msgid);
563	    if (ret != 0) {
564	        DEV_MON_ERR("hdc msg format error: %d\n", ret);
565	        goto dm_hdc_server_free_hdc_msg;
566	    }
567	    hdc_msg->session = (unsigned long long)(uintptr_t)session;
568	    hdc_msg->msg_type = msg_type;
569	
570	    ret = drvHdcAllocMsg(session, &p_msg_snd, 1);
571	    if (ret != OK) {
572	        DEV_MON_ERR("%s %d alloc msg err, ret %d\n", __FUNCTION__, __LINE__, ret);
573	        goto dm_hdc_server_free_hdc_msg;
574	    }
575	
576	    ret = (int)drvHdcAddMsgBuffer(p_msg_snd, (char *)hdc_msg, (int)(HDCMSG_HEAD_SIZE + hdc_msg->data_len));
577	    if (ret != OK) {
578	        DEV_MON_ERR("%s %d add msg err, ret %d\n", __FUNCTION__, __LINE__, ret);
579	        goto dm_hdc_server_free_msg;
580	    }
581	
582	    ret = halHdcSend(session, p_msg_snd, HDC_FLAG_WAIT_TIMEOUT, HDC_MSG_TIMEOUT);
583	    if (ret != OK) {
584	        DEV_MON_ERR("%s %d send err, ret %d\n", __FUNCTION__, __LINE__, ret);
585	        goto dm_hdc_server_free_msg;
586	    }
587	
588	dm_hdc_server_free_msg:
589	    (void)drvHdcFreeMsg(p_msg_snd);
590	    p_msg_snd = NULL;
591	dm_hdc_server_free_hdc_msg:
592	    free(hdc_msg);
593	    hdc_msg = NULL;
594	    /* server CLOSE */
595	    (void)drvHdcSessionClose(session);
596	    dstaddr->hdc_work_status = HDC_ADDR_CLOSE;
597	    return ret;
598	}
