689	STATIC int __dm_hdc_recv(DM_INTF_S *intf, int fd, short revents, DM_RECV_ST *irecv)
690	{
691	    HDC_MSG_ST *msg = NULL;
692	    DM_HDC_ADDR_ST *addr = (DM_HDC_ADDR_ST *)irecv->addr;
693	    DM_HDC_ADDR_ST *myaddr = NULL;
694	    DEV_MP_MSG_ST *msg_content = NULL;
695	    int ret;
696	    unsigned short tmp_event = (unsigned short)revents;
697	    myaddr = (DM_HDC_ADDR_ST *)&(intf->my_addr);
698	    (void)intf;
699	
700	    if ((tmp_event & POLLIN) != 0) {
701	        msg = (HDC_MSG_ST *)malloc(sizeof(HDC_MSG_ST));
702	        DRV_CHECK_RETV((msg != NULL), -ENOMEM);
703	        ret = memset_s(msg, sizeof(HDC_MSG_ST), 0, (sizeof(HDC_MSG_ST)));
704	
705	        return_val_do_info((ret != 0), -EINVAL, msg, DEV_MON_ERR("__dm_hdc_recv: memset_s fail.errno=%d\n", errno));
706	
707	        /* read msg from selfloop channel */
708	        ret = (int)mm_read_file(fd, (void *)msg, HDCMSG_HEAD_SIZE);
709	        if (ret != HDCMSG_HEAD_SIZE) {
710	            DEV_MON_ERR("%s%d\n", "__dm_hdc_recv: read fail.errno=", errno);
711	            free(msg);
712	            msg = NULL;
713	            return -1;
714	        }
715	
716	        if ((msg->data_len) > DM_MSG_DATA_MAX) {
717	            DEV_MON_ERR("%s%d\n", "__dm_hdc_recv: msg->data_len too long=", msg->data_len);
718	            free(msg);
719	            msg = NULL;
720	            return -1;
721	        }
722	
723	        ret = (int)mm_read_file(fd, (void *)msg->data, msg->data_len);
724	        if (msg->data_len != ret) {
725	            DEV_MON_ERR("%s%d\n", "__dm_hdc_recv: read fail.errno=", errno);
726	            free(msg);
727	            msg = NULL;
728	            return -1;
729	        }
730	        irecv->recv_type = msg->msg_type;
731	        /* get source address */
732	        addr = (DM_HDC_ADDR_ST *)irecv->addr;
733	        addr->addr_type = DM_HDC_ADDR_TYPE;
734	        addr->channel = DM_HDC_CHANNEL;
735	        addr->hdc_type = ((myaddr->hdc_type) ? 0 : 1);
736	        addr->peer_node = msg->src_devid;
737	        addr->peer_devid = msg->peer_devid;
738	        addr->session = msg->session;
739	        addr->hdc_work_status = HDC_ADDR_WORK;
740	        irecv->addr_len = sizeof(*addr);
741	        irecv->msgid = msg->msgid;
742	        irecv->dev_id = myaddr->dev_id;
743	
744	        /* get session property from hdc in server */
745	        if (myaddr->hdc_type == DMP_SERVER) {
746	            ret = dm_get_session_propery(irecv, msg);
747	            DRV_CHECK_RETV_DO_SOMETHING((ret == 0), ret,
748	                                        (void)drvHdcSessionClose((HDC_SESSION)addr->session);
749	                                        DEV_MON_ERR("get session property failed.\n"));
750	        }
751	
752	        if (irecv->msg.data_len >= msg->data_len) {
753	            irecv->msg.data_len = msg->data_len;
754	        }
755	
756	        if (irecv->msg.data_len && (irecv->msg.data_len <= DM_MSG_DATA_MAX)) {
757	            ret = memcpy_s(irecv->msg.data, irecv->msg.data_len, msg->data,
758	                           irecv->msg.data_len);
759	            DRV_CHECK_RETV_DO_SOMETHING((ret == 0), ret, free(msg);
760	                                        msg = NULL;
761	                                        (void)drvHdcSessionClose((HDC_SESSION)addr->session);
762	                                        DEV_MON_ERR("memcpy_s error\n"));
763	        }
764	
765	        // update content data_len for security reason
766	        msg_content = (DEV_MP_MSG_ST *)irecv->msg.data;
767	        msg_content->length = (unsigned int)(irecv->msg.data_len < (unsigned short)(sizeof(DEV_MP_MSG_ST)) ? 0 :
768	            irecv->msg.data_len - sizeof(DEV_MP_MSG_ST));
769	        free(msg);
770	        msg = NULL;
771	    }
772	
773	    return 0;
774	}
775	
776	STATIC void __dm_hdc_close(DM_INTF_S *intf)
777	{
778	    int ret;
779	    DM_HDC_CB_ST *chan_cb = NULL;
780	    DM_HDC_ADDR_ST *myaddr = NULL;
781	    g_dm_hdc_run = 0;
782	    ret = strncmp(intf->name, DM_HDC_INTF, strlen(DM_HDC_INTF));
783	    if (ret != 0) {
784	        DEV_MON_ERR("strncmp failed, %s cannot match %s\n", intf->name, DM_HDC_INTF);
785	        return;
786	    }
787	
788	    myaddr = (DM_HDC_ADDR_ST *)&(intf->my_addr);
789	    chan_cb = (DM_HDC_CB_ST *)(intf->channel_cb);
790	
791	    if (chan_cb != NULL) {
792	        if (!myaddr->hdc_type) {
793	            (void)drvHdcClientDestroy((HDC_CLIENT)chan_cb->cb);
794	        } else {
795	            (void)drvHdcServerDestroy((HDC_SERVER)chan_cb->cb);
796	        }
797	        free(intf->channel_cb);
798	        intf->channel_cb = NULL;
799	    }
800	
801	    ret = mm_close_file(intf->rfd);
802	    DRV_CHECK_CHK(ret == 0);
803	    ret = mm_close_file(intf->wfd);
804	    DRV_CHECK_CHK(ret == 0);
805	    return;
806	}
807	
808	int dm_hdc_init(DM_INTF_S **my_intf, DM_CB_S *cb, DM_MSG_TIMEOUT_HNDL_T timeout_hndl, DM_ADDR_ST *my_addr,
809	                const char *my_name, int name_len)
810	{
811	    DM_INTF_S *intf = NULL;
812	    char name[sizeof(intf->name)] = {0};
813	    struct drvHdcCapacity capacity = {0};
814	    int ret;
815	    DM_HDC_ADDR_ST *hdc_addr = (DM_HDC_ADDR_ST *)my_addr;
816	    unsigned int channel_max_trans_len;
817	
818	    if (cb == NULL) {
819	        return -EINVAL;
820	    }
821	
822	    if ((my_addr == NULL) || (my_addr->addr_type != DM_HDC_ADDR_TYPE) || (my_addr->channel != DM_HDC_CHANNEL)) {
823	        return -EINVAL;
824	    }
825	
826	    if ((my_name != NULL) && (name_len >= (int)sizeof(intf->name))) {
827	        return -EINVAL;
828	    }
829	
830	    ret = dm_hdc_get_intf_name(hdc_addr->dev_id, name, sizeof(intf->name));
831	    if (ret != 0) {
832	        return ret;
833	    }
834	
835	    ret = drvHdcGetCapacity(&capacity);
836	    if (ret != 0) {
837	        DEV_MON_ERR("drvHdcGetCapacity fail: %d\n", ret);
838	        return ret;
839	    }
840	
841	    name[sizeof(name) - 1] = 0;
842	    intf = dm_get_intf(cb, name, (int)strlen(name));
843	    if (intf != NULL) {
844	        DEV_MON_ERR("duplicate interface [%s]\r\n", name);
845	        return -EBUSY;
846	    }
847	
848	    intf = calloc(1, sizeof(*intf));
849	    if (intf == NULL) {
850	        return -ENOMEM;
851	    }
852	
853	    ret = strncpy_s(intf->name, sizeof(intf->name), name, sizeof(intf->name) - 1);
854	    DRV_CHECK_RETV_DO_SOMETHING((ret == 0), ret, free(intf);
855	                                intf = NULL;
856	                                DEV_MON_ERR("strncpy_s error\n"));
857	    intf->name[DM_INTF_NAME_LEN - 1] = '\0';
858	    intf->my_addr = *my_addr;
859	    ret = __dm_hdc_open(intf);
860	    if (ret != 0) {
861	        free(intf);
862	        intf = NULL;
863	        return ret;
864	    }
865	
866	    intf->retries = 0;
867	    intf->retry_time_ms = DSMI_MSG_TIMEOUT;
868	    /* Data frame format: | dm: hdc msg head | dm msg head | dm cmd payload | */
869	    channel_max_trans_len = capacity.maxSegment > DM_MSG_DATA_MAX ? DM_MSG_DATA_MAX : capacity.maxSegment;
870	    DRV_CHECK_RETV_DO_SOMETHING((channel_max_trans_len > (unsigned int)HDCMSG_HEAD_SIZE), -EINVAL,
871	                                DEV_MON_ERR("Hdc channel length is abnormal.\n");
872	                                __dm_hdc_close(intf);
873	                                free(intf); intf = NULL);
874	    intf->max_trans_len = (unsigned int)(channel_max_trans_len - HDCMSG_HEAD_SIZE);
875	    intf->recv_msg = __dm_hdc_recv;
876	    intf->send_msg = __dm_hdc_send;
877	    intf->send_msg_settime = __dm_hdc_settime_send;
878	    intf->set_retries = __dm_hdc_set_retries;
879	    intf->get_retries = __dm_hdc_get_retries;
880	    intf->close = __dm_hdc_close;
881	    intf->timeout_hndl = timeout_hndl;
882	    intf->dm_cb = (void *)cb;
883	    intf->stats.pipe_wr_fail = 0;
884	    intf->stats.msg_handle_timeout = 0;
885	    ret = dm_intf_register(cb, intf);
886	    if (ret != 0) {
887	        DEV_MON_ERR("dm_hdc_init->dm_intf_register fail.\n");
888	        __dm_hdc_close(intf);
889	        free(intf);
890	        intf = NULL;
891	        return ret;
892	    }
893	
894	    if (my_intf != NULL) {
895	        *my_intf = intf;
896	    }
897	
898	    return 0;
899	}
