43	STATIC void __dm_timeout_handle(int interval, int elapsed, void *user_data, int data_len)
44	{
45	    PENDING_REQ_T *req = *((PENDING_REQ_T **)user_data);
46	    DM_INTF_S *intf = NULL;
47	    DM_CB_S *cb = NULL;
48	    int ret;
49	    intptr_t tmpptr;
50	    (void)elapsed;
51	    (void)data_len;
52	    tmpptr = (intptr_t)req;
53	
54	    if ((req == NULL) || (req->intf == NULL) || (req->intf->dm_cb == NULL)) {
55	        DEV_MON_ERR("__dm_timeout_handle input user_data null!\n");
56	        return;
57	    }
58	
59	    intf = req->intf;
60	    cb = (DM_CB_S *)intf->dm_cb;
61	
62	    /* judge if support retry */
63	    if (req->retries > 0) {
64	        /* resend the msg and change value of retries */
65	        req->retries--;
66	        ret = intf->send_msg(intf, REQUEST_MSG, &req->addr, req->addr_len, &req->msg, (signed long)tmpptr);
67	        if (ret == 0) {
68	            DEV_MON_INFO("process timeout, retry call intf->send_msg ret = %d\n", ret);
69	            /* read the timer
70	               if retries >= 0, auto-response 0xC3 when timeout
71	               if retries < 0, do nothing    */
72	            ret = poller_timer_add(cb->intf_poller, interval, __dm_timeout_handle, &req, sizeof(PENDING_REQ_T *),
73	                                   &req->timer_id);
74	        }
75	
76	        /* if resend msg fail, just stop */
77	        if (ret != 0) {
78	            DEV_MON_INFO("finish call intf->send_msg");
79	            req->retries = 0;
80	        }
81	    }
82	
83	    /* if no retry, send the requester the timeout msg */
84	    if (req->retries == 0) {
85	        /* through timeout interface to return C3(timeout) */
86	        DM_INTF_S *selfloop = NULL;
87	        DM_MSG_ST msg;
88	        /* fill in timeout code with through timeout_hndl */
89	        msg = req->msg;
90	        intf->timeout_hndl(&req->msg, &msg);
91	        DEV_MON_INFO("finish call intf->timeout_hndl\n");
92	
93	        /* judge the interface of user is selfloop interface */
94	        if (strncmp(intf->name, SELFLOOP_INTF, sizeof(intf->name)) != 0) {
95	            selfloop = dm_get_intf(cb, SELFLOOP_INTF, sizeof(SELFLOOP_INTF));
96	        } else {
97	            selfloop = intf;
98	        }
99	
100	        if (selfloop != NULL) {
101	            (void)dm_send_rsp(selfloop, (DM_ADDR_ST *)(&req->addr), req->addr_len, &msg, (signed long)tmpptr);
102	            DEV_MON_INFO("finish call dm_send_rsp\n");
103	        }
104	    }
105	
106	    return;
107	}
