141	STATIC int __dm_pending_req_add(DM_INTF_S *intf, const DM_ADDR_ST *addr, unsigned int addr_len, const DM_MSG_ST *msg,
142	                                DM_MSG_CMD_HNDL_T rsp_hndl, const void *user_data, int data_len,
143	                                PENDING_REQ_T **pending_req)
144	{
145	    DM_CB_S *cb = (DM_CB_S *)(intf->dm_cb);
146	    PENDING_REQ_T *req = NULL;
147	    int ret;
148	    DATA_LEN_CHECK();
149	    req = malloc(sizeof(*req));
150	    if (req == NULL) {
151	        return -ENOMEM;
152	    }
153	
154	    ret = memset_s((void *)req, sizeof(*req), 0, sizeof(*req));
155	    if (ret != 0) {
156	        DEV_MON_ERR("memset_s fail: %d\n", ret);
157	        free(req);
158	        req = NULL;
159	        return ret;
160	    }
161	
162	    *pending_req = req;
163	    req->intf = intf;
164	    req->addr = *addr;
165	    req->addr_len = addr_len;
166	    req->rsp_hndl = rsp_hndl;
167	    /* copy the message, for retries */
168	    req->msg = *msg;
169	
170	    if (req->msg.data_len > sizeof(req->msg_data)) {
171	        req->msg.data_len = sizeof(req->msg_data);
172	    }
173	
174	    req->msg.data = req->msg_data;
175	    ret = memmove_s(req->msg_data, DM_MSG_DATA_MAX, msg->data, req->msg.data_len);
176	    DRV_CHECK_RETV_DO_SOMETHING((ret == 0), ret, free(req);
177	                                req = NULL;
178	                                DEV_MON_ERR("memmove_s error\n"));
179	
180	    /* copy the user_data */
181	    if ((user_data != NULL) && data_len != 0) {
182	        req->user_data = malloc((size_t)data_len);
183	
184	        if (req->user_data == NULL) {
185	            free(req);
186	            req = NULL;
187	            return -ENOMEM;
188	        }
189	
190	        ret = memset_s((void *)req->user_data, (size_t)data_len, 0, (size_t)data_len);
191	        if (ret != 0) {
192	            DEV_MON_ERR("memset_s fail: %d\n", ret);
193	            free(req->user_data);
194	            req->user_data = NULL;
195	            free(req);
196	            req = NULL;
197	            return ret;
198	        }
199	
200	        ret = memmove_s(req->user_data, (size_t)data_len, user_data, (size_t)data_len);
201	        DRV_CHECK_RETV_DO_SOMETHING((ret == 0), ret, free(req->user_data);
202	                                    req->user_data = NULL;
203	                                    free(req);
204	                                    req = NULL;
205	                                    DEV_MON_ERR("memmove_s error\n"));
206	        req->data_len = data_len;
207	    }
208	
209	    /* add timeout handler */
210	    req->retries = intf->retries;
211	
212	    if (req->retries >= 0) {
213	        /* if retries >= 0, auto-response 0xC3 when timeout
214	           if retries < 0, do nothing */
215	        ret = poller_timer_add(cb->intf_poller, (int)intf->retry_time_ms, __dm_timeout_handle, &req, sizeof(PENDING_REQ_T *),
216	                               &req->timer_id);
217	        if (ret != 0) {
218	            free(req->user_data);
219	            req->user_data = NULL;
220	            free(req);
221	            req = NULL;
222	            return ret;
223	        }
224	    }
225	
226	    /* add to pending list */
227	    ret = list_append(cb->pending_list, req);
228	    if (ret != 0) {
229	        if (req->retries >= 0) {
230	            (void)poller_timer_remove(cb->intf_poller, &req->timer_id);
231	        }
232	
233	        free(req->user_data);
234	        req->user_data = NULL;
235	        free(req);
236	        req = NULL;
237	        return ret;
238	    }
239	
240	    DEV_MON_INFO("finish __dm_pending_req_add\n");
241	    return 0;
242	}
