270	STATIC void __dm_pending_req_del(DM_INTF_S *intf, signed long long msgid)
271	{
272	    DM_CB_S *cb = (DM_CB_S *)(intf->dm_cb);
273	    PENDING_REQ_T *req = NULL;
274	    PENDING_REQ_T *item = NULL;
275	    LIST_NODE_T *node = NULL;
276	    LIST_ITER_T iter = {0};
277	    bool find = FALSE;
278	
279	    req = (PENDING_REQ_T *)(uintptr_t)msgid;
280	
281	    list_iter_init(cb->pending_list, &iter);
282	    while ((node = list_iter_next(&iter)) != NULL) {
283	        if (list_to_item(node) == req) {
284	            find = TRUE;
285	            break;
286	        }
287	    }
288	
289	    if (find) {
290	        item = (PENDING_REQ_T *)list_to_item(node);
291	        if (item->retries >= 0) {
292	            /* if has retry, should delete timer from timer_list
293	               which is added when send msg */
294	            (void)poller_timer_remove(cb->intf_poller, &item->timer_id);
295	        }
296	        /* if no retry, just delete the node from pending_list */
297	        (void)list_remove_by_tag(cb->pending_list, item, __dm_pending_req_cmp);
298	    }
299	
300	    list_iter_destroy(&iter);
301	
302	    return;
303	}
