305	STATIC void __dm_rsp_handle(DM_INTF_S *intf, DM_RECV_ST *precv)
306	{
307	    DM_CB_S *cb = (DM_CB_S *)(intf->dm_cb);
308	    PENDING_REQ_T *req = NULL;
309	    PENDING_REQ_T *item = NULL;
310	    LIST_NODE_T *node = NULL;
311	    LIST_ITER_T iter = {0};
312	    bool find = FALSE;
313	    /*
314	     * About the use of msgid:
315	     * send address of PENDING_REQ_T as msgid, when resp comes back,
316	     * we can find the PENDING_REQ_T based on the msgid right time.
317	     */
318	    req = (PENDING_REQ_T *)(uintptr_t)precv->msgid;
319	    list_iter_init(cb->pending_list, &iter);
320	
321	    while ((node = list_iter_next(&iter)) != NULL) {
322	        if (list_to_item(node) == req) {
323	            find = TRUE;
324	            break;
325	        }
326	    }
327	
328	    if (find && (unsigned long)(uintptr_t)req != 0) {
329	        item = (PENDING_REQ_T *)list_to_item(node);
330	        if (item->rsp_hndl != NULL) {
331	            /* call user's rsp_handle to handle data */
332	            item->rsp_hndl(intf, precv, req->user_data, req->data_len);
333	        }
334	
335	        __dm_pending_req_del(intf, precv->msgid);
336	    }
337	
338	    list_iter_destroy(&iter);
339	
340	    return;
341	}
