343	STATIC void __dm_cmd_handle(DM_INTF_S *intf, DM_RECV_ST *precv)
344	{
345	    bool find = FALSE;
346	    LIST_NODE_T *node = NULL;
347	    LIST_ITER_T iter = {0};
348	    DM_CB_S *ipmi_cb = (DM_CB_S *)(intf->dm_cb);
349	    DM_CMD_REGISTER_T *cmd = NULL;
350	
351	    list_iter_init(ipmi_cb->cmd_reg_list, &iter);
352	
353	    if ((node = list_iter_next(&iter)) != NULL) {
354	        cmd = list_to_item(node);
355	        if (cmd == NULL) {
356	            DEV_MON_ERR("__dm_cmd_handle: cmd is null\n");
357	            return;
358	        }
359	        find = TRUE;
360	    }
361	
362	    /* if find no cmd, use ipmi_send_rsp() to send resp */
363	    if (!find) {
364	        DM_MSG_ST msg;
365	        /* fill in unsupported info with calling DM_MSG_UNSUP_HNDL_T */
366	        msg = precv->msg;
367	        ipmi_cb->unsup_hndl(&precv->msg, &msg);
368	        /* send response */
369	        (void)dm_send_rsp(intf, (DM_ADDR_ST *)precv->addr, precv->addr_len, &msg, precv->msgid);
370	    } else {
371	        if ((cmd != NULL) && (cmd->hndl != NULL)) {
372	            /* call user's cmd function to handle data */
373	            cmd->hndl(intf, precv, cmd->user_data, cmd->data_len);
374	        }
375	    }
376	
377	    list_iter_destroy(&iter);
378	
379	    return;
380	}
