382	STATIC void __dm_msg_handle(DM_INTF_S *intf, DM_RECV_ST *precv)
383	{
384	    switch (precv->recv_type) {
385	        case RESPONSE_MSG:
386	            __dm_rsp_handle(intf, precv);
387	            break;
388	
389	        case REQUEST_MSG:
390	            __dm_cmd_handle(intf, precv);
391	            break;
392	
393	        default:
394	            break;
395	    }
396	
397	    return;
398	}
