400	STATIC void dm_recv_time_check(DM_INTF_S *intf, struct timespec start, struct timespec end)
401	{
402	    long recv_time;
403	
404	    recv_time = (end.tv_sec * MS_PER_SECOND + end.tv_nsec / NS_PER_MSECOND) -
405	                (start.tv_sec * MS_PER_SECOND + start.tv_nsec / NS_PER_MSECOND);
406	    if (recv_time > DM_RECV_HANDLE_TIMEOUT) {
407	        intf->stats.msg_handle_timeout++;
408	        if ((intf->stats.msg_handle_timeout >= DM_RECV_HANDLE_TIMEOUT_CNT) &&
409	            (intf->stats.msg_handle_timeout <= DM_RECV_HANDLE_TIMEOUT_MAX)) {
410	            DEV_MON_ERR("Recv handle cost long time. (intf_name=%s; timeout=%u; recv_time=%llums)\n",
411	                intf->name, intf->stats.msg_handle_timeout, recv_time);
412	        }
413	    } else {
414	        intf->stats.msg_handle_timeout = 0;
415	    }
416	}
