418	STATIC void __dm_recv(int fd, short revents, void *user_data, int data_len)
419	{
420	    DM_INTF_S *intf = *((DM_INTF_S **)user_data);
421	    unsigned char *data = NULL;
422	    DM_ADDR_ST addr = {0};
423	    DM_RECV_ST st_recv = {0};
424	    int ret;
425	    struct timespec time_start = { 0, 0 };
426	    struct timespec time_end = { 0, 0 };
427	
428	    (void)data_len;
429	
430	    if (intf == NULL) {
431	        DEV_MON_ERR("__dm_recv: intf is null.\n");
432	        return;
433	    }
434	
435	    if (intf->recv_msg == NULL) {
436	        DEV_MON_ERR("__dm_recv: intf->recv_msg is null.\n");
437	        return;
438	    }
439	
440	    data = (unsigned char *)malloc(DM_MSG_DATA_MAX);
441	    DRV_CHECK_RET((data != NULL));
442	    ret = memset_s(data, DM_MSG_DATA_MAX, 0, DM_MSG_DATA_MAX);
443	    if (ret != 0) {
444	        DEV_MON_ERR("memset_s fail. (ret=%d)\n", ret);
445	        free(data);
446	        data = NULL;
447	        return;
448	    }
449	
450	    st_recv.msg.data = data;
451	    st_recv.msg.data_len = DM_MSG_DATA_MAX;
452	    st_recv.addr = (unsigned char *)&addr;
453	    st_recv.addr_len = sizeof(addr);
454	    st_recv.dev_id = 0;
455	
456	    if (intf->recv_msg != NULL) {
457	        /* call intf->recv_msg to receive msg */
458	        (void)clock_gettime(CLOCK_MONOTONIC, &time_start);
459	        ret = intf->recv_msg(intf, fd, revents, &st_recv);
460	        if (ret == 0) {
461	            /* handle msg */
462	            __dm_msg_handle(intf, &st_recv);
463	        }
464	        (void)clock_gettime(CLOCK_MONOTONIC, &time_end);
465	        dm_recv_time_check(intf, time_start, time_end);
466	    }
467	
468	    free(data);
469	    data = NULL;
470	    return;
471	}
