604	DM_INTF_S *dm_get_intf(DM_CB_S *cb, const char *name, int name_len)
605	{
606	    DM_INTF_S *intf = NULL;
607	    DM_INTF_S *tmp = NULL;
608	    LIST_NODE_T *node = NULL;
609	    LIST_ITER_T iter = {0};
610	    int ret = 0;
611	
612	    if ((cb == NULL) || (name == NULL) || name_len > DM_INTF_NAME_LEN) {
613	        DEV_MON_ERR("dm_get_intf input cb or name null ,name len %d larger than %d\n", name_len, DM_INTF_NAME_LEN);
614	        return NULL;
615	    }
616	
617	    list_iter_init(cb->intf_list, &iter);
618	
619	    while ((node = list_iter_next(&iter)) != NULL) {
620	        tmp = (DM_INTF_S *)(list_to_item(node));
621	        if (tmp == NULL) {
622	            DEV_MON_ERR("dm_get_intf:tmp is null!\n");
623	            break;
624	        }
625	
626	        ret = strncmp(tmp->name, name, sizeof(tmp->name));
627	        if (ret == 0) {
628	            intf = tmp;
629	            break;
630	        }
631	    }
632	
633	    list_iter_destroy(&iter);
634	    return intf;
635	}
636	
637	int dm_init(DM_CB_S **dm_cb)
638	{
639	    DM_CB_S *cb = NULL;
640	    int ret;
641	
642	    if (dm_cb == NULL) {
643	        DEV_MON_ERR("dm_init input dm_cb null.");
644	        return -EINVAL;
645	    }
646	
647	    cb = malloc(sizeof(DM_CB_S));
648	    if (cb == NULL) {
649	        DEV_MON_ERR("dm_init malloc cb error.");
650	        return -ENOMEM;
651	    }
652	
653	    ret = memset_s((void *)cb, sizeof(DM_CB_S), 0, sizeof(DM_CB_S));
654	    if (ret != 0) {
655	        DEV_MON_ERR("memset_s fail: %d\n", ret);
656	        free(cb);
657	        cb = NULL;
658	        return ret;
659	    }
660	
661	    cb->cmd_reg_list = NULL;
662	    cb->intf_list = NULL;
663	    cb->intf_poller = NULL;
664	    cb->pending_list = NULL;
665	    *dm_cb = cb;
666	    ret = poller_create(&(cb->intf_poller));
667	    if (ret != 0) {
668	        DEV_MON_ERR("call poller_create fail,ret:%d\r\n", ret);
669	        goto out;
670	    }
671	
672	    ret = poller_run(cb->intf_poller);
673	    if (ret != 0) {
674	        DEV_MON_ERR("call poller_run fail,ret:%d\r\n", ret);
675	        goto out;
676	    }
677	
678	    ret = list_create(&(cb->intf_list), __dm_intf_cmp, __dm_intf_free);
679	    if (ret != 0) {
680	        DEV_MON_ERR("create intf list fail,ret:%d\r\n", ret);
681	        goto out;
682	    }
683	
684	    ret = list_create(&(cb->pending_list), __dm_pending_req_cmp, __dm_pending_req_free);
685	    if (ret != 0) {
686	        DEV_MON_ERR("create pending list fail,ret:%d\r\n", ret);
687	        goto out;
688	    }
689	
690	    ret = list_create(&(cb->cmd_reg_list), __dm_cmd_handler_cmp, __dm_cmd_handler_free);
691	    if (ret != 0) {
692	        DEV_MON_ERR("create cmd_reg_list fail,ret:%d\r\n", ret);
693	        goto out;
694	    }
695	
696	    ret = selfloop_init(NULL, cb, NULL, NULL, 0);
697	    if (ret != 0) {
698	        DEV_MON_ERR("selfloop init fail,ret:%d\r\n", ret);
699	        goto out;
700	    }
701	
702	out:
703	
704	    if (ret != 0) {
705	        dm_destroy(cb);
706	        *dm_cb = NULL;
707	    }
708	
709	    return ret;
710	}
711	
712	int dm_intf_register(DM_CB_S *cb, DM_INTF_S *intf)
713	{
714	    int ret;
715	
716	    if ((cb == NULL) || (intf == NULL)) {
717	        DEV_MON_ERR("dm_intf_register input cb or intf null.\n");
718	        return -EINVAL;
719	    }
720	
721	    ret = list_append(cb->intf_list, intf);
722	    if (ret != 0) {
723	        return ret;
724	    }
725	
726	    /* add openipmi fd into fd_list of poller */
727	    ret = poller_fd_add(cb->intf_poller, intf->rfd, POLLIN, __dm_recv, &intf, sizeof(DM_INTF_S *));
728	    if (ret != 0) {
729	        (void)list_del_by_tag(cb->intf_list, intf, __dm_intf_cmp);
730	        return ret;
731	    }
732	
733	    return 0;
734	}
735	
736	int dm_intf_deregister(DM_INTF_S *intf)
737	{
738	    int ret;
739	    DM_CB_S *cb = NULL;
740	
741	    if (intf == NULL) {
742	        DEV_MON_ERR("dm_intf_deregister input intf null.\n");
743	        return -EINVAL;
744	    }
745	
746	    cb = (DM_CB_S *)intf->dm_cb;
747	    ret = poller_fd_remove(cb->intf_poller, intf->rfd, POLLIN);
748	    if (ret == 0) {
749	        ret = list_remove_by_tag(cb->intf_list, intf, __dm_intf_cmp);
750	    }
751	
752	    return ret;
753	}
754	
755	int dm_send_req(DM_INTF_S *intf, DM_ADDR_ST *addr, unsigned int addr_len, const DM_MSG_ST *msg,
756	                DM_MSG_CMD_HNDL_T rsp_hndl, const void *user_data, int data_len)
757	{
758	    PENDING_REQ_T *p_req = NULL;
759	    int ret;
760	    intptr_t tmpptr;
761	    DSMI_DFT_RES_CMD *send_msg = NULL;
762	    unsigned short opcode = INVALID_OPCODE;
763	
764	    if ((intf == NULL) || (addr == NULL) || (addr_len == 0) || (msg == NULL)) {
765	        return DRV_ERROR_PARA_ERROR;
766	    }
767	
768	    /* print opcode */
769	    if (msg->data != NULL) {
770	        send_msg = (DSMI_DFT_RES_CMD *)(msg->data);
771	        opcode = send_msg->opcode;
772	    } else {
773	        DEV_MON_ERR("MSG data is NULL.\n");
774	    }
775	
776	    /* add msg into pending list */
777	    ret = __dm_pending_req_add(intf, addr, addr_len, msg, rsp_hndl, user_data, data_len, &p_req);
778	    if (ret != 0) {
779	        return DRV_ERROR_INNER_ERR;
780	    }
781	
782	    tmpptr = (intptr_t)p_req;
783	    /* call intf->send msg function to send msg */
784	    if (intf->send_msg != NULL) {
785	        ret = intf->send_msg(intf, REQUEST_MSG, addr, addr_len, msg, (long)tmpptr);
786	        DEV_MON_DEBUG("finish call intf->send_msg, ret = %d\n", ret);
787	        /* if send fail , do not handle */
788	        if (ret != 0) {
789	            DEV_MON_ERR("failed call intf->send_msg, ret = %d, send_msg->opcode = 0x%x.\n", ret, opcode);
790	            ret = DRV_ERROR_SEND_MESG;
791	        }
792	        DEV_MON_DEBUG("finish call dm_send_req\n");
793	    }
794	
795	    return ret;
796	}
797	
798	int dm_send_rsp(DM_INTF_S *intf, DM_ADDR_ST *addr, unsigned int addr_len, const DM_MSG_ST *msg,
799	                signed long seq_no)
800	{
801	    int ret;
802	    if ((intf == NULL) || (intf->send_msg == NULL)) {
803	        DEV_MON_ERR("Invalid parameter. (intf_is_null=%d or intf->send_msg=null)\n", (intf != NULL));
804	        return DRV_ERROR_PARA_ERROR;
805	    }
806	    /* send rep message */
807	    ret = intf->send_msg(intf, RESPONSE_MSG, addr, addr_len, msg, (long)seq_no);
808	    return ret;
809	}
